package campfire.routes

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import java.io.File

/**
 * `vectors/campfire_routes.json`, generated by `reference-tools/campfire/routes.rb`: the route
 * table as `bin/rails routes` lists it, and sample paths with what `recognize_path` made of them.
 * Read the way the `Vectors` struct in `crates/campfire/src/controllers.rs` deserializes it.
 */
object RouteVectors {
    /** A row of `bin/rails routes`. */
    data class RailsRoute(val verb: String, val path: String, val endpoint: String, val defaults: Map<String, String>)

    /** A sample path and the endpoint (null when Rails raised) and params Rails recognized. */
    data class Sample(val verb: String, val path: String, val endpoint: String?, val params: Map<String, String>)

    private val root: JsonNode by lazy {
        val directory = System.getProperty("campfire.vectors") ?: error("the campfire.vectors property is not set")
        ObjectMapper().readTree(File(directory, "campfire_routes.json"))
    }

    /** The `routes` array. */
    val routes: List<RailsRoute> by lazy {
        root["routes"].map { RailsRoute(it["verb"].asText(), it["path"].asText(), it["endpoint"].asText(), strings(it["defaults"])) }
    }

    /** The `recognitions` array. */
    val recognitions: List<Sample> by lazy {
        root["recognitions"].map {
            val endpoint = it["endpoint"]
            Sample(it["verb"].asText(), it["path"].asText(), if (endpoint.isNull) null else endpoint.asText(), strings(it["params"]))
        }
    }

    /** A JSON object of strings as a map. */
    private fun strings(node: JsonNode): Map<String, String> =
        node.properties().associate { (key, value) -> key to value.asText() }
}
